<?php
require '../app/core/bootstrap.php';auth();require '../app/core/layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('INSERT INTO evaluaciones_calidad(producto_id,adhesion,secado,acabado,durabilidad,rendimiento,calidad_precio,comentarios,usuario_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([(int)$_POST['producto_id'],(float)$_POST['adhesion'],(float)$_POST['secado'],(float)$_POST['acabado'],(float)$_POST['durabilidad'],(float)$_POST['rendimiento'],(float)$_POST['cp'],$_POST['comentarios']?:null,$_SESSION['uid']]);flash('Evaluación registrada.');redirect('calidad.php');}
$ps=$pdo->query('SELECT id,nombre FROM productos WHERE activo=1 ORDER BY nombre')->fetchAll();$rows=$pdo->query('SELECT e.*,p.nombre,ROUND((adhesion+secado+acabado+durabilidad+rendimiento+calidad_precio)/6,2) score FROM evaluaciones_calidad e JOIN productos p ON p.id=e.producto_id ORDER BY e.id DESC')->fetchAll();head('Calidad');
?><div class="card card-body mb-3"><h2 class="h5">Nueva evaluación</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-2"><div class="col-md-3"><select name="producto_id" class="form-select" required><option value="">Producto</option><?php foreach($ps as $p):?><option value="<?=$p['id']?>"><?=e($p['nombre'])?></option><?php endforeach?></select></div><?php foreach(['adhesion'=>'Adhesión','secado'=>'Secado','acabado'=>'Acabado','durabilidad'=>'Durabilidad','rendimiento'=>'Rendimiento','cp'=>'Calidad/precio'] as $n=>$l):?><div class="col"><label class="small"><?=e($l)?></label><input name="<?=$n?>" type="number" min="0" max="10" step=".1" value="8" class="form-control"></div><?php endforeach?></div><textarea name="comentarios" class="form-control mt-2" placeholder="Observaciones"></textarea><button class="btn btn-primary mt-2">Guardar evaluación</button></form></div><div class="card"><div class="card-body p-0"><table class="table mb-0"><thead><tr><th>Producto</th><th>Score</th><th>Comentarios</th><th>Fecha</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><strong><?=e($r['score'])?>/10</strong></td><td><?=e($r['comentarios'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div></div><?php foot();
